wwv_flow_imp_shared.create_task_def_action(
 p_id=>wwv_flow_imp.id(168071325553947465313)
,p_task_def_id=>wwv_flow_imp.id(166645201628602381111)
,p_name=>'UPDATE LEAVE TABLE AND LEAVE APEX TAKS TABLE'
,p_static_id=>'update-leave-table'
,p_execution_sequence=>60
,p_on_event=>'COMPLETE'
,p_action_type=>'NATIVE_PLSQL'
,p_action_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- BEGIN',
'',
'--     -- UPDATE LEAVE TABLE',
'',
'--     UPDATE LWF_LEAVES',
'--     SET STATUS = CASE ',
'--                       WHEN :APEX$TASK_OUTCOME = ''REJECTED''THEN ''HR_REJECTED''',
'--                       ELSE :APEX$TASK_OUTCOME',
'--                 END,',
'--         APPROVED_BY     = CASE ',
'--                           WHEN :APEX$TASK_OUTCOME = ''APPROVED''',
'--                           THEN :APEX$TASK_OWNER',
'--                         END,',
'--         APPROVED_AT     = CASE ',
'--                             WHEN :APEX$TASK_OUTCOME = ''APPROVED''',
'--                             THEN SYSTIMESTAMP',
'--                           END,',
'--         REJECTED_BY     = CASE ',
'--                             WHEN :APEX$TASK_OUTCOME = ''REJECTED''',
'--                             THEN :APEX$TASK_OWNER',
'--                           END,',
'--         REJECTED_AT     = CASE ',
'--                             WHEN :APEX$TASK_OUTCOME = ''REJECTED''',
'--                             THEN SYSTIMESTAMP',
'--                           END,',
'--         UPDATED_BY      = :APEX$TASK_OWNER,',
'--         UPDATED_AT = SYSTIMESTAMP',
'--     WHERE LEAVE_ID = :LEAVE_ID;',
'',
'--     PKG_LWF_LEAVE_APEX_TASKS.UPDATE_LWF_LEAVE_APEX_TASKS(:LEAVE_ID, 2, :APEX$TASK_ID);',
'',
'--     APEX_MAIL.PUSH_QUEUE;',
'-- END;',
'',
'DECLARE',
'    l_comment VARCHAR2(4000);',
'BEGIN',
'',
'    -- BEGIN',
'    --     SELECT TEXT',
'    --     INTO l_comment',
'    --     FROM (',
'    --         SELECT TEXT',
'    --         FROM APEX_TASK_COMMENTS',
'    --         WHERE TASK_ID = :APEX$TASK_ID',
'    --         ORDER BY CREATED_ON DESC',
'    --     )',
'    --     WHERE ROWNUM = 1;',
'    -- EXCEPTION',
'    --     WHEN NO_DATA_FOUND THEN',
'    --         l_comment := NULL;',
'    -- END;',
'',
'    BEGIN',
'        SELECT LISTAGG(TEXT, '', '')',
'           WITHIN GROUP (ORDER BY CREATED_ON)',
'        INTO l_comment',
'        FROM APEX_TASK_COMMENTS',
'        WHERE TASK_ID = :APEX$TASK_ID;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            l_comment := NULL;',
'    END;',
'',
'    -- UPDATE LEAVE TABLE',
'    UPDATE LWF_LEAVES',
'    SET STATUS = CASE ',
'                    WHEN :APEX$TASK_OUTCOME = ''REJECTED'' THEN ''HR_REJECTED''',
'                    ELSE :APEX$TASK_OUTCOME',
'                 END,',
'',
'        APPROVED_BY = CASE ',
'                        WHEN :APEX$TASK_OUTCOME = ''APPROVED''',
'                        THEN :APEX$TASK_OWNER',
'                      END,',
'',
'        APPROVED_AT = CASE ',
'                        WHEN :APEX$TASK_OUTCOME = ''APPROVED''',
'                        THEN SYSTIMESTAMP',
'                      END,',
'',
'        APPROVAL_REASON = CASE',
'                            WHEN :APEX$TASK_OUTCOME = ''APPROVED''',
'                            THEN l_comment',
'                          END,',
'',
'        REJECTED_BY = CASE ',
'                        WHEN :APEX$TASK_OUTCOME = ''REJECTED''',
'                        THEN :APEX$TASK_OWNER',
'                      END,',
'',
'        REJECTED_AT = CASE ',
'                        WHEN :APEX$TASK_OUTCOME = ''REJECTED''',
'                        THEN SYSTIMESTAMP',
'                      END,',
'',
'        REJECTION_REASON = CASE',
'                             WHEN :APEX$TASK_OUTCOME = ''REJECTED''',
'                             THEN l_comment',
'                           END,',
'',
'        UPDATED_BY = :APEX$TASK_OWNER,',
'        UPDATED_AT = SYSTIMESTAMP',
'',
'    WHERE LEAVE_ID = :LEAVE_ID;',
'',
'    PKG_LWF_LEAVE_APEX_TASKS.UPDATE_LWF_LEAVE_APEX_TASKS(:LEAVE_ID, 2, :APEX$TASK_ID);',
'',
'    APEX_MAIL.PUSH_QUEUE;',
'END;'))
,p_action_clob_language=>'PLSQL'
,p_location=>'LOCAL'
,p_stop_execution_on_error=>true
,p_created_on=>wwv_flow_imp.dz('20260512000000Z')
,p_updated_on=>wwv_flow_imp.dz('20260818101621Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
wwv_flow_imp_shared.create_task_def_action(
 p_id=>wwv_flow_imp.id(167851785638033697956)
,p_task_def_id=>wwv_flow_imp.id(166645201628602381111)
,p_name=>'UPDATE LEAVE TABLE AND INSERT INTO APEX TASK TABLE'
,p_static_id=>'update-leave-table-and-insert-into-apex-task-table'
,p_execution_sequence=>20
,p_on_event=>'CREATE'
,p_action_type=>'NATIVE_PLSQL'
,p_action_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'',
'    -- UPDATE LEAVE TABLE',
'',
'    UPDATE LWF_LEAVES',
'    SET STATUS = ''PENDING_HR'',',
'    APPROVAL_LEVEL = 2,',
'    TASK_ID = TASK_ID || '', '' || :APEX$TASK_ID',
'    WHERE LEAVE_ID = :LEAVE_ID;',
'',
'    PKG_LWF_LEAVE_APEX_TASKS.INSERT_LWF_LEAVE_APEX_TASKS(:LEAVE_ID, 2, :APEX$TASK_ID);',
'',
'    APEX_MAIL.PUSH_QUEUE;',
'END;'))
,p_action_clob_language=>'PLSQL'
,p_location=>'LOCAL'
,p_stop_execution_on_error=>true
,p_created_on=>wwv_flow_imp.dz('20260511000000Z')
,p_updated_on=>wwv_flow_imp.dz('20260520124946Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
wwv_flow_imp_shared.create_task_def_participant(
 p_id=>wwv_flow_imp.id(166646225522940057311)
,p_task_def_id=>wwv_flow_imp.id(166645201628602381111)
,p_participant_type=>'POTENTIAL_OWNER'
,p_identity_type=>'USER'
,p_value_type=>'SQL_QUERY'
,p_value=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT UPPER(EMAIL) FROM LWF_USERS',
'WHERE ROLE_ID = 2',
'AND DEPARTMENT_ID =(SELECT DEPARTMENT_ID FROM LWF_USERS',
'WHERE USER_ID = :EMPLOYEE_ID);'))
,p_created_on=>wwv_flow_imp.dz('20260507043452Z')
,p_updated_on=>wwv_flow_imp.dz('20260520044612Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
