wwv_flow_imp_shared.create_task_def_action(
 p_id=>wwv_flow_imp.id(167852303049582007231)
,p_task_def_id=>wwv_flow_imp.id(166446025939156219621)
,p_name=>'UPDATE LEAVE TABLE'
,p_static_id=>'update-leave-table'
,p_execution_sequence=>60
,p_on_event=>'COMPLETE'
,p_action_type=>'NATIVE_PLSQL'
,p_action_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- BEGIN',
'',
'--     -- UPDATE LEAVE TABLE',
'--     IF :TOTAL_DAYS > 2 THEN',
'',
'--         UPDATE LWF_LEAVES',
'--         SET STATUS = ''PENDING_HR''',
'--         WHERE LEAVE_ID = :LEAVE_ID;',
'',
'--     ELSE',
'--         UPDATE LWF_LEAVES',
'--         SET STATUS = CASE ',
'--                           WHEN :APEX$TASK_OUTCOME = ''REJECTED''THEN ''MANAGER_REJECTED''',
'--                           ELSE :APEX$TASK_OUTCOME',
'--                     END,',
'--             APPROVED_BY     = CASE ',
'--                               WHEN :APEX$TASK_OUTCOME = ''APPROVED''',
'--                               THEN :APEX$TASK_OWNER',
'--                             END,',
'--             APPROVED_AT     = CASE ',
'--                                 WHEN :APEX$TASK_OUTCOME = ''APPROVED''',
'--                                 THEN SYSTIMESTAMP',
'--                               END,',
'--             REJECTED_BY     = CASE ',
'--                                 WHEN :APEX$TASK_OUTCOME = ''REJECTED''',
'--                                 THEN :APEX$TASK_OWNER',
'--                               END,',
'--             REJECTED_AT     = CASE ',
'--                                 WHEN :APEX$TASK_OUTCOME = ''REJECTED''',
'--                                 THEN SYSTIMESTAMP',
'--                               END,',
'--             UPDATED_BY      = :APEX$TASK_OWNER,',
'--             UPDATED_AT = SYSTIMESTAMP',
'--         WHERE LEAVE_ID = :LEAVE_ID;',
'',
'--     END IF;',
'--     PKG_LWF_LEAVE_APEX_TASKS.UPDATE_LWF_LEAVE_APEX_TASKS(:LEAVE_ID, 1, :APEX$TASK_ID);',
'',
'--     APEX_MAIL.PUSH_QUEUE;',
'-- END;',
'',
'DECLARE',
'    l_comment VARCHAR2(4000);',
'BEGIN',
'',
'    -- BEGIN',
'    --     SELECT TEXT',
'    --     INTO l_comment',
'    --     FROM (',
'    --         SELECT TEXT',
'    --         FROM APEX_TASK_COMMENTS',
'    --         WHERE TASK_ID = :APEX$TASK_ID',
'    --         ORDER BY CREATED_ON DESC',
'    --     )',
'    --     WHERE ROWNUM = 1;',
'    -- EXCEPTION',
'    --     WHEN NO_DATA_FOUND THEN',
'    --         l_comment := NULL;',
'    -- END;',
'',
'',
'    BEGIN',
'        SELECT LISTAGG(TEXT, '', '')',
'           WITHIN GROUP (ORDER BY CREATED_ON)',
'        INTO l_comment',
'        FROM APEX_TASK_COMMENTS',
'        WHERE TASK_ID = :APEX$TASK_ID;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            l_comment := NULL;',
'    END;',
'',
'    IF :TOTAL_DAYS > 2 THEN',
'',
'        UPDATE LWF_LEAVES',
'        SET STATUS = ''PENDING_HR''',
'        WHERE LEAVE_ID = :LEAVE_ID;',
'',
'    ELSE',
'        UPDATE LWF_LEAVES',
'        SET STATUS = CASE ',
'                        WHEN :APEX$TASK_OUTCOME = ''REJECTED'' THEN ''MANAGER_REJECTED''',
'                        ELSE :APEX$TASK_OUTCOME',
'                     END,',
'',
'            APPROVED_BY = CASE ',
'                            WHEN :APEX$TASK_OUTCOME = ''APPROVED''',
'                            THEN :APEX$TASK_OWNER',
'                          END,',
'',
'            APPROVED_AT = CASE ',
'                            WHEN :APEX$TASK_OUTCOME = ''APPROVED''',
'                            THEN SYSTIMESTAMP',
'                          END,',
'',
'            APPROVAL_REASON = CASE',
'                                WHEN :APEX$TASK_OUTCOME = ''APPROVED''',
'                                THEN l_comment',
'                              END,',
'',
'            REJECTED_BY = CASE ',
'                            WHEN :APEX$TASK_OUTCOME = ''REJECTED''',
'                            THEN :APEX$TASK_OWNER',
'                          END,',
'',
'            REJECTED_AT = CASE ',
'                            WHEN :APEX$TASK_OUTCOME = ''REJECTED''',
'                            THEN SYSTIMESTAMP',
'                          END,',
'',
'            REJECTION_REASON = CASE',
'                                 WHEN :APEX$TASK_OUTCOME = ''REJECTED''',
'                                 THEN l_comment',
'                               END,',
'',
'            UPDATED_BY = :APEX$TASK_OWNER,',
'            UPDATED_AT = SYSTIMESTAMP',
'',
'        WHERE LEAVE_ID = :LEAVE_ID;',
'',
'    END IF;',
'',
'    PKG_LWF_LEAVE_APEX_TASKS.UPDATE_LWF_LEAVE_APEX_TASKS(:LEAVE_ID, 1, :APEX$TASK_ID);',
'',
'    APEX_MAIL.PUSH_QUEUE;',
'END;'))
,p_action_clob_language=>'PLSQL'
,p_location=>'LOCAL'
,p_stop_execution_on_error=>true
,p_created_on=>wwv_flow_imp.dz('20260511000000Z')
,p_updated_on=>wwv_flow_imp.dz('20260819090826Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
