prompt --application/shared_components/navigation/lists/lwf_dynamic_navigation_menu
begin
wwv_flow_imp_shared.create_list(
 p_id=>wwv_flow_imp.id(165728766069884984394)
,p_name=>'LWF_DYNAMIC_NAVIGATION_MENU'
,p_static_id=>'lwf-dynamic-navigation-menu'
,p_list_type=>'SQL_QUERY'
,p_list_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH user_access AS (',
'    SELECT DISTINCT',
'        NM.MENU_ID,',
'        NM.PARENT_MENU_ID,',
'        NM.MENU_NAME,',
'        NM.MENU_SEQ_ID,',
'        NM.ICON,',
'        P.APEX_PAGE_ID',
'    FROM ',
'        LWF_USERS U',
'        -- JOIN DEMO_RBA_USER_ROLE_ACCESS_MASTER URAM ON U.USER_ID = URAM.USER_ID',
'       -- JOIN PRMS_ROLE_MASTER R ON URAM.DEFAULT_ROLE_ID = R.ROLE_ID',
'    JOIN LWF_ROLES R ',
'      ON R.ROLE_ID = U.ROLE_ID ',
'        JOIN LWF_ROLE_PAGE_ACCESS_MASTER RPAM ON R.ROLE_ID = RPAM.ROLE_ID',
'        JOIN LWF_PAGE_MASTER P ON RPAM.PAGE_ID = P.PAGE_ID',
'        JOIN LWF_NAVIGATION_MENU_MASTER NM ON NM.PAGE_ID = RPAM.PAGE_ID',
'    WHERE ',
'        U.USER_ID = :USER_ID',
'),',
'all_menus AS (',
'    -- accessible menus',
'    SELECT ',
'        MENU_ID, ',
'        PARENT_MENU_ID, ',
'        MENU_NAME, ',
'        MENU_SEQ_ID,',
'        ICON,',
'        APEX_PAGE_ID',
'    FROM user_access',
'    UNION',
'    -- add parents even if no direct role access',
'    SELECT ',
'        NM.MENU_ID,',
'        NM.PARENT_MENU_ID,',
'        NM.MENU_NAME,',
'        NM.MENU_SEQ_ID,',
'        NM.ICON,',
'        NM.APEX_PAGE_ID',
'    FROM LWF_NAVIGATION_MENU_MASTER NM',
'    WHERE NM.MENU_ID IN (',
'        SELECT DISTINCT PARENT_MENU_ID ',
'        FROM user_access ',
'        WHERE PARENT_MENU_ID IS NOT NULL',
'    )',
')',
'SELECT',
'    LEVEL,                        ',
'    MENU_NAME AS label,           ',
'    CASE ',
'        WHEN APEX_PAGE_ID IS NOT NULL THEN',
'            ''f?p=''||:APP_ID||'':''||APEX_PAGE_ID||'':''||:APP_SESSION||'':::::''',
'        ELSE NULL',
'    END AS target,',
'    CASE ',
'        WHEN APEX_PAGE_ID = :APP_PAGE_ID THEN ''YES''',
'        ELSE ''NO''',
'    END AS is_current_list_entry,',
'    ICON AS image,',
'    NULL AS image_attribute,',
'    NULL AS image_alt_attribute,',
'    MENU_ID AS attribute1',
'FROM all_menus',
'START WITH PARENT_MENU_ID IS NULL',
'CONNECT BY PRIOR MENU_ID = PARENT_MENU_ID',
'ORDER SIBLINGS BY MENU_SEQ_ID NULLS LAST',
''))
,p_version_scn=>'SH256:WScCVo8-WPvQ6AlMa0iDjRcB5w3c7Ft2AMsJkNXMdEc'
,p_created_on=>wwv_flow_imp.dz('20260504094243Z')
,p_updated_on=>wwv_flow_imp.dz('20260515071842Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
end;
