prompt --application/shared_components/email/templates/leave_approval_request_mail_to_hr
begin
wwv_flow_imp_shared.create_email_template(
 p_id=>wwv_flow_imp.id(166723210850927580285)
,p_name=>'Leave Approval Request Mail to HR'
,p_static_id=>'LEAVE_APPROVAL_REQUEST_MAIL_TO_HR'
,p_version_number=>2
,p_subject=>unistr('Leave Approval Request \2013 #EMPLOYEE_NAME#')
,p_html_body=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<!DOCTYPE html>',
'<html>',
'',
'<head>',
'    <meta charset="UTF-8">',
'    <title>Leave Approval Request</title>',
'</head>',
'',
'<body style="font-family: Arial, sans-serif; background-color: #f4f4f4; padding: 20px;">',
'    <table width="100%" cellpadding="0" cellspacing="0">',
'        <tr>',
'            <td align="center">',
'                <table width="600" cellpadding="0" cellspacing="0"',
'                    style="background-color: #ffffff; border-radius: 10px; overflow: hidden;"> <!-- Header -->',
'                    <tr>',
'                        <td style="background-color: #2563eb; color: #ffffff; padding: 20px; text-align: center;">',
'                            <h2 style="margin: 0;">Leave Approval Request</h2>',
'                        </td>',
'                    </tr> <!-- Body -->',
'                    <tr>',
'                        <td style="padding: 30px; color: #333333;">',
'                            <p>Dear <b>#HR_NAME#</b>,</p>',
'                            <p> A leave request has been Apptoved by Manager(#MANAGER_NAME#) and is awaiting HR approval. </p>',
'                            <table width="100%" cellpadding="10" cellspacing="0"',
'                                style="border-collapse: collapse; margin-top: 20px;">',
'                                <tr style="background-color: #f9fafb;">',
'                                    <td><b>Employee Name</b></td>',
'                                    <td>#EMPLOYEE_NAME#</td>',
'                                </tr>',
'                                <tr>',
'                                    <td><b>Leave Type</b></td>',
'                                    <td>#LEAVE_TYPE#</td>',
'                                </tr>',
'                                <tr style="background-color: #f9fafb;">',
'                                    <td><b>From Date</b></td>',
'                                    <td>#FROM_DATE#</td>',
'                                </tr>',
'                                <tr>',
'                                    <td><b>To Date</b></td>',
'                                    <td>#TO_DATE#</td>',
'                                </tr>',
'                                <tr style="background-color: #f9fafb;">',
'                                    <td><b>Total Days</b></td>',
'                                    <td>#TOTAL_DAYS#</td>',
'                                </tr>',
'                                <tr>',
'                                    <td><b>Reason</b></td>',
'                                    <td>#REASON#</td>',
'                                </tr>',
'                            </table>',
'                            <p style="margin-top: 30px;"> Please review and take the necessary action. </p>',
'                            <p> Regards,<br> <b>Leave Management System</b> </p>',
'                        </td>',
'                    </tr> <!-- Footer -->',
'                    <tr>',
'                        <td',
'                            style="background-color: #f3f4f6; text-align: center; padding: 15px; font-size: 12px; color: #6b7280;">',
'                            This is an automated email. Please do not reply. </td>',
'                    </tr>',
'                </table>',
'            </td>',
'        </tr>',
'    </table>',
'</body>',
'',
'</html>'))
,p_version_scn=>'15766761697139'
,p_created_on=>wwv_flow_imp.dz('20260507084841Z')
,p_updated_on=>wwv_flow_imp.dz('20260507085015Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
end;
