,p_triggering_element_type=>'ITEM'
,p_triggering_element=>'P13_LEAVE_TYPE_ID,P13_LEAVE_DAYS'
,p_bind_type=>'bind'
,p_execution_type=>'IMMEDIATE'
,p_bind_event_type=>'change'
,p_created_on=>wwv_flow_imp.dz('20260505072818Z')
,p_updated_on=>wwv_flow_imp.dz('20260511075245Z')
