wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(156688306225451048048)
,p_event_id=>wwv_flow_imp.id(156688306184819048047)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_static_id=>'native-execute-plsql-code'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'items_to_return', 'P13_IS_LEAVE_TAKE',
  'items_to_submit', 'P13_LEAVE_TYPE_ID,P13_LEAVE_DAYS,USER_ID',
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'DECLARE',
    '    v_leave_type varchar2(255);',
    '    v_remaining_leave number;',
    'BEGIN',
    '    SELECT ',
    '        LT.LEAVE_NAME,',
    '        L.AVAILABLE_LEAVES',
    '    INTO ',
    '        v_leave_type,',
    '        v_remaining_leave',
    '    FROM LWF_LEAVE_TYPE LT',
    '    JOIN LWF_LEAVES_TAKEN L ON',
    '    LT.LEAVE_ID = L.LEAVE_TYPE_ID',
    '    WHERE L.LEAVE_TYPE_ID = :P13_LEAVE_TYPE_ID',
    '    AND L.USER_ID = :USER_ID',
    '    AND L.YEAR = EXTRACT(YEAR FROM SYSDATE)',
    '    FETCH FIRST ROW ONLY;',
    '',
    '    IF :P13_LEAVE_DAYS > v_remaining_leave THEN',
    '        :P13_IS_LEAVE_TAKE := ''Requested for '' || :P13_LEAVE_DAYS || '' but for '' || v_leave_type || '' you have only '' || v_remaining_leave || '' remaining leaves '';',
    '    ELSE',
    '        :P13_IS_LEAVE_TAKE := NULL;',
    '    END IF;',
    '',
    '    EXCEPTION',
    '        WHEN NO_DATA_FOUND THEN ',
    '',
    '        SELECT ',
    '            LEAVE_NAME ',
    '        INTO ',
    '            v_leave_type',
    '        FROM LWF_LEAVE_TYPE ',
    '        WHERE LEAVE_ID = :P13_LEAVE_TYPE_ID;',
    '',
    '        :P13_IS_LEAVE_TAKE := ''No leave allocation found for '' || v_leave_type ||'' . Please contact HR for further details.'';',
    '',
    'END;')),
  'show_processing', 'Y',
  'suppress_change_event', 'N')).to_clob
,p_wait_for_result=>'Y'
,p_created_on=>wwv_flow_imp.dz('20260505072818Z')
,p_updated_on=>wwv_flow_imp.dz('20260511075245Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
