wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(156688304926210048035)
,p_event_id=>wwv_flow_imp.id(156688304865807048034)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_static_id=>'native-execute-plsql-code'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'items_to_return', 'P13_REMAINING_LEAVE_MESSAGE',
  'items_to_submit', 'P13_LEAVE_TYPE_ID,USER_ID',
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'DECLARE',
    '    v_leave_type varchar2(255);',
    '    v_remaining_leave number;',
    '    v_total_leaves number;',
    'BEGIN',
    '        SELECT ',
    '            L.LEAVE_NAME,',
    '            LT.TOTAL_ALLOCATED_LEAVE,',
    '            LT.AVAILABLE_LEAVES',
    '        INTO ',
    '            v_leave_type,',
    '            v_total_leaves,',
    '            v_remaining_leave',
    '        FROM LWF_LEAVES_TAKEN LT   ',
    '        JOIN LWF_LEAVE_TYPE L',
    '        ON L.LEAVE_ID = LT.LEAVE_TYPE_ID',
    '        WHERE LT.USER_ID = :USER_ID  ',
    '        AND LT.LEAVE_TYPE_ID = :P13_LEAVE_TYPE_ID',
    '        AND LT.YEAR = EXTRACT(YEAR FROM SYSDATE)',
    '        FETCH FIRST ROW ONLY;',
    '',
    '        :P13_REMAINING_LEAVE_MESSAGE := ''You have '' || v_remaining_leave || '' remaining out of '' || v_total_leaves || '' allocated '' || v_leave_type || '' days.'';',
    '    ',
    '        IF v_remaining_leave <= 0 THEN',
    '            :P13_IS_LEAVE_AVAILABLE := ''N'';',
    '        ELSE',
    '            :P13_IS_LEAVE_AVAILABLE := ''Y'';',
    '        END IF;',
    '',
    '    EXCEPTION',
    '        WHEN NO_DATA_FOUND THEN ',
    '',
    '        SELECT ',
    '            LEAVE_NAME ',
    '        INTO ',
    '            v_leave_type',
    '        FROM LWF_LEAVE_TYPE ',
    '        WHERE LEAVE_ID = :P13_LEAVE_TYPE_ID;',
    '',
    '        :P13_REMAINING_LEAVE_MESSAGE := ''No leave allocation found for '' || v_leave_type ||'' . Please contact HR for further details.'';',
    '',
    '        :P13_IS_LEAVE_AVAILABLE := ''N'';',
    'END;')),
  'show_processing', 'Y',
  'suppress_change_event', 'N')).to_clob
,p_wait_for_result=>'Y'
,p_created_on=>wwv_flow_imp.dz('20260504130836Z')
,p_updated_on=>wwv_flow_imp.dz('20260511075245Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
