'    var $ = apex.jQuery,',
'',
'        toolbarData = $.apex.interactiveGrid.copyDefaultToolbar();',
' ',
'    // remove unwanted groups',
'',
'    toolbarData.toolbarRemove("reports");',
'',
'    toolbarData.toolbarRemove("views");',
'',
'    toolbarData.toolbarRemove("actions2");',
'',
'    toolbarData.toolbarRemove("actions3");',
' ',
'    // Keep actions4 (right-most group)',
'',
'    var rightGroup = toolbarData.toolbarFind("actions4");',
' ',
'    // Add custom button to right group',
'',
'    rightGroup.controls.push({',
'',
'        type: "BUTTON",',
'',
'        label: "Create",',
'',
'        icon: "fa fa-plus",',
'',
'        iconBeforeLabel: true,',
'',
'        hot: true,',
'',
'        action: "open_dailog"',
'',
'    });',
' ',
'    // Define action',
'',
'    config.initActions = function(actions) {',
'',
'        actions.add({',
'',
'            name: "open_dailog",',
'',
'            action: function() { $.event.trigger(''open_dailog''); }',
'',
'        });',
'',
'    };',
' ',
'    config.toolbarData = toolbarData;',
'',
'    return config;',
'',
'}',
'',
' '))
,p_updated_on=>wwv_flow_imp.dz('20260504061913Z')
