wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(166720367821418854422)
,p_plug_name=>'Pending Leave'
,p_static_id=>'pending-leave'
,p_parent_plug_id=>wwv_flow_imp.id(166720367737740854421)
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select L.LEAVE_ID,',
'       L.USER_ID,',
'       L.LEAVE_TYPE_ID,',
'       L.FROM_DATE,',
'       L.TO_DATE,',
'       L.REASON,',
'       L.LEAVE_DAYS,',
'       INITCAP(REPLACE(L.STATUS, ''_'', '' '')) AS STATUS,',
'       case L.STATUS',
'         when ''MANAGER_REJECTED''  then ''t-Badge--danger''',
'         when ''HR_REJECTED''  then ''t-Badge--danger''',
'         when ''PENDING_HR''    then ''t-Badge--warning''',
'         when ''PENDING_MANAGER''    then ''t-Badge--warning''',
'         when ''CANCELLED'' then ''t-Badge--info''',
'         when ''APPROVED'' then ''t-Badge--success''',
'         else ''t-Badge--neutral''',
'    end as STATUS_BADGE_STATE,',
'       L.APPROVED_BY,',
'       L.APPROVED_AT,',
'       L.APPROVAL_REASON,',
'       L.REJECTED_BY,',
'       L.REJECTED_AT,',
'       L.REJECTION_REASON,',
'       L.TASK_ID,',
'       L.WORKFLOW_ID,',
'       L.APPROVAL_LEVEL,',
'       L.CREATED_AT,',
'       L.CREATED_BY,',
'       L.UPDATED_AT,',
'       L.UPDATED_BY,',
'       T.TASK_ID AS WORKFLOW_TASK_ID, ',
'	   T.TASK_DEF_ID, ',
'	   T.TASK_DEF_NAME, ',
'	   T.TASK_DEF_STATIC_ID, ',
'	   T.SUBJECT, ',
'	   T.TASK_TYPE, ',
'	   T.DUE_ON, ',
'	   T.PRIORITY, ',
'	   T.PRIORITY_LEVEL, ',
'	   T.DETAIL_PK, ',
'	   T.INITIATOR, ',
'	   T.INITIATOR_CAN_COMPLETE, ',
'	   T.ACTUAL_OWNER, ',
'	   T.STATE_CODE, ',
'	   T.STATE, ',
'	   T.OUTCOME_CODE, ',
'	   CASE',
'        WHEN T.OUTCOME IS NULL THEN ''Pending''',
'        ELSE T.OUTCOME',
'       END AS TASK_STATUS, ',
'	   T.CREATED_BY AS TASK_CREATED_BY, ',
'	   T.CREATED_ON, ',
'	   T.LAST_UPDATED_BY, ',
'	   T.LAST_UPDATED_ON,',
'       NULL AS ACTION',
'  from LWF_LEAVES L',
'  LEFT JOIN LWF_LEAVE_APEX_TASKS LAT ON L.LEAVE_ID = LAT.LEAVE_ID',
'  LEFT JOIN (',
'    SELECT ',
'        TASK_ID, ',
'	    TASK_DEF_ID, ',
'	    TASK_DEF_NAME, ',
'	    TASK_DEF_STATIC_ID, ',
'	    SUBJECT, ',
'	    TASK_TYPE, ',
'	    DUE_ON, ',
'	    PRIORITY, ',
'	    PRIORITY_LEVEL, ',
'	    DETAIL_PK, ',
'	    INITIATOR, ',
'	    INITIATOR_CAN_COMPLETE, ',
'	    ACTUAL_OWNER, ',
'	    STATE_CODE, ',
'	    STATE, ',
'	    OUTCOME_CODE, ',
'	    OUTCOME, ',
'	    CREATED_BY, ',
'	    CREATED_ON, ',
'	    LAST_UPDATED_BY, ',
'	    LAST_UPDATED_ON',
'    FROM TABLE(',
'        apex_approval.get_tasks(',
'            p_context => ''MY_TASKS'',',
