wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(293013655684535716)
,p_plug_name=>'Rejected Leaves'
,p_static_id=>'rejected-leaves'
,p_parent_plug_id=>wwv_flow_imp.id(166720367737740854421)
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>30
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select L.LEAVE_ID,',
'       L.USER_ID,',
'       L.LEAVE_TYPE_ID,',
'       L.FROM_DATE,',
'       L.TO_DATE,',
'       L.REASON,',
'       L.LEAVE_DAYS,',
'       INITCAP(REPLACE(L.STATUS, ''_'', '' '')) AS STATUS,',
'       case L.STATUS',
'         when ''MANAGER_REJECTED''  then ''t-Badge--danger''',
'         when ''HR_REJECTED''  then ''t-Badge--danger''',
'         when ''PENDING_HR''    then ''t-Badge--warning''',
'         when ''PENDING_MANAGER''    then ''t-Badge--warning''',
'         when ''CANCELLED'' then ''t-Badge--info''',
'         when ''APPROVED'' then ''t-Badge--success''',
'         else ''t-Badge--neutral''',
'    end as STATUS_BADGE_STATE,',
'       L.APPROVED_BY,',
'       L.APPROVED_AT,',
'       L.APPROVAL_REASON,',
'       L.REJECTED_BY,',
'       L.REJECTED_AT,',
'       L.REJECTION_REASON,',
'       L.TASK_ID,',
'       L.WORKFLOW_ID,',
'       L.APPROVAL_LEVEL,',
'       L.CREATED_AT,',
'       L.CREATED_BY,',
'       L.UPDATED_AT,',
'       L.UPDATED_BY',
'  from LWF_LEAVES L',
'  LEFT JOIN LWF_LEAVE_APEX_TASKS LAT ON L.LEAVE_ID = LAT.LEAVE_ID',
' WHERE UPPER(LAT.ACTUAL_OWNER) = UPPER(:USER_EMAIL)',
' AND  LAT.OUTCOME_CODE = ''REJECTED'''))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
